create table if not exists public.ils_professional_assignment_security_review_queue (id uuid primary key default gen_random_uuid(), escalation_id uuid, decision text not null check(decision in ('REVIEW','STOP')), severity text not null check(severity in ('MEDIUM','HIGH','CRITICAL')), source_failure_code text, observed_count bigint, review_status text not null default 'PENDING' check(review_status in ('PENDING','IN_REVIEW','APPROVED','REJECTED','CLOSED')), required_approval_level text not null default 'HUMAN', assigned_reviewer_id uuid, reviewer_note text, created_at timestamptz not null default now(), reviewed_at timestamptz, unique(escalation_id)); alter table public.ils_professional_assignment_security_review_queue enable row level security; alter table public.ils_professional_assignment_security_review_queue force row level security; revoke all on public.ils_professional_assignment_security_review_queue from anon,authenticated; create table if not exists public.ils_professional_assignment_security_review_approval_log (id uuid primary key default gen_random_uuid(), queue_id uuid not null, reviewer_id uuid, approval_decision text not null check(approval_decision in ('APPROVE','REJECT')), approved_action text, approval_reason text not null, created_at timestamptz not null default now()); alter table public.ils_professional_assignment_security_review_approval_log enable row level security; alter table public.ils_professional_assignment_security_review_approval_log force row level security; revoke all on public.ils_professional_assignment_security_review_approval_log from anon,authenticated; create table if not exists public.ils_professional_assignment_security_review_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_security_review_tests enable row level security; alter table public.ils_professional_assignment_security_review_tests force row level security; revoke all on public.ils_professional_assignment_security_review_tests from anon,authenticated; insert into public.ils_professional_assignment_security_review_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('PENDING_REVIEW','NO_ACTION','NO_ACTION',true,'New review items cannot execute mutation-channel actions while pending.'),('STOP_REVIEW','HUMAN_APPROVAL','HUMAN_APPROVAL',true,'Critical STOP items require human review/approval.'),('CLIENT_APPROVAL','BLOCK','BLOCK',true,'Customer/client approval cannot substitute for security reviewer approval.'),('SELF_APPROVAL','BLOCK','BLOCK',true,'The affected professional cannot self-approve a security action.'),('UNAUTHORIZED_REVIEWER','BLOCK','BLOCK',true,'Only explicitly authorized human security reviewers may approve.'),('REJECTED_ACTION','BLOCK','BLOCK',true,'Rejected review items cannot execute the proposed action.'),('APPROVED_ACTION','CONTROLLED','CONTROLLED',true,'Approval only authorizes the specifically approved action.'),('ACTION_SCOPE','EXACT_MATCH','EXACT_MATCH',true,'Approved action must match the queued action; no scope expansion.'),('AUDIT_LOG','REQUIRED','REQUIRED',true,'Every approval/rejection is recorded in an immutable approval log.'),('DUPLICATE_REVIEW','BLOCK_DUPLICATE','BLOCK_DUPLICATE',true,'One queue item per escalation prevents duplicate review records.'),('DIRECT_CLIENT_WRITE','BLOCK','BLOCK',true,'Queue and approval log remain backend-only.'),('EMPTY_LIVE_QUEUE','PASS','PASS',true,'No synthetic review item is created while live alerts are absent.');